import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.pages().listPages(Map.of("search", "about", "visibility", "open", "sort", "name", "order", "asc"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("pages")) {
    Map<?, ?> page = (Map<?, ?>) row;
    System.out.println(page.get("id") + " " + page.get("name") + " " + page.get("url") + " " + page.get("visibility"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

